PRAGMA foreign_keys = ON;
CREATE TABLE users (id TEXT PRIMARY KEY, handle TEXT NOT NULL COLLATE NOCASE UNIQUE, password_hash TEXT NOT NULL, salt TEXT NOT NULL, recovery_hash TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'player' CHECK(role IN ('player','host','moderator','editor','administrator')), status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','muted','suspended','banned')), created_at TEXT NOT NULL);
CREATE TABLE profiles (user_id TEXT PRIMARY KEY REFERENCES users(id), display_name TEXT NOT NULL, bio TEXT NOT NULL DEFAULT '', country TEXT NOT NULL DEFAULT '', avatar TEXT NOT NULL DEFAULT '', banner TEXT NOT NULL DEFAULT '', color TEXT NOT NULL DEFAULT 'teal', font TEXT NOT NULL DEFAULT 'condensed', games TEXT NOT NULL DEFAULT '', platform TEXT NOT NULL DEFAULT '', gamertag TEXT NOT NULL DEFAULT '', region TEXT NOT NULL DEFAULT '', preferred_role TEXT NOT NULL DEFAULT '', presence TEXT NOT NULL DEFAULT 'offline');
CREATE TABLE sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), expires_at INTEGER NOT NULL);
CREATE TABLE rate_limits (key TEXT PRIMARY KEY, count INTEGER NOT NULL, reset_at INTEGER NOT NULL);
CREATE TABLE games (id TEXT PRIMARY KEY, title TEXT NOT NULL UNIQUE COLLATE NOCASE, platform TEXT NOT NULL DEFAULT '', genre TEXT NOT NULL DEFAULT '', image TEXT NOT NULL DEFAULT '', publisher TEXT NOT NULL DEFAULT '');
INSERT INTO games(id,title,genre) VALUES ('cod','Call of Duty','FPS'),('halo','Halo','FPS'),('fortnite','Fortnite','Battle Royale'),('apex','Apex Legends','Battle Royale'),('r6','Rainbow Six Siege','FPS'),('tekken','Tekken','Fighting'),('sf','Street Fighter','Fighting'),('mk','Mortal Kombat','Fighting'),('rl','Rocket League','Sports'),('madden','Madden','Sports'),('nba','NBA 2K','Sports'),('forza','Forza','Racing'),('f1','F1','Racing');
CREATE TABLE tournaments (id TEXT PRIMARY KEY, slug TEXT NOT NULL UNIQUE, title TEXT NOT NULL, game TEXT NOT NULL, format TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'Draft', owner_id TEXT NOT NULL, data TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX tournament_status ON tournaments(status,created_at DESC);
CREATE TABLE registrations (id TEXT PRIMARY KEY, tournament_id TEXT NOT NULL REFERENCES tournaments(id), user_id TEXT NOT NULL REFERENCES users(id), status TEXT NOT NULL DEFAULT 'pending', checked_in INTEGER NOT NULL DEFAULT 0, seed INTEGER, created_at TEXT NOT NULL, UNIQUE(tournament_id,user_id));
CREATE TABLE invite_codes (id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE, tournament_id TEXT NOT NULL REFERENCES tournaments(id), max_uses INTEGER, uses INTEGER NOT NULL DEFAULT 0, expires_at TEXT, auto_approve INTEGER NOT NULL DEFAULT 0, enabled INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);
CREATE TABLE brackets (tournament_id TEXT PRIMARY KEY REFERENCES tournaments(id), data TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 1, mutation TEXT NOT NULL);
CREATE TABLE matches (id TEXT PRIMARY KEY, tournament_id TEXT NOT NULL REFERENCES tournaments(id), round INTEGER NOT NULL, status TEXT NOT NULL, data TEXT NOT NULL);
CREATE INDEX match_tournament ON matches(tournament_id,round);
CREATE TABLE result_submissions (id TEXT PRIMARY KEY, tournament_id TEXT NOT NULL, match_id TEXT NOT NULL, user_id TEXT NOT NULL, data TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'Awaiting Verification', created_at TEXT NOT NULL);
CREATE TABLE follows (follower_id TEXT NOT NULL REFERENCES users(id), following_id TEXT NOT NULL REFERENCES users(id), PRIMARY KEY(follower_id,following_id), CHECK(follower_id<>following_id));
CREATE TABLE groups (id TEXT PRIMARY KEY, handle TEXT NOT NULL UNIQUE COLLATE NOCASE, name TEXT NOT NULL, description TEXT NOT NULL, owner_id TEXT NOT NULL REFERENCES users(id), privacy TEXT NOT NULL, games TEXT NOT NULL DEFAULT '', avatar TEXT NOT NULL DEFAULT '', banner TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL);
CREATE TABLE group_members (group_id TEXT NOT NULL REFERENCES groups(id), user_id TEXT NOT NULL REFERENCES users(id), role TEXT NOT NULL DEFAULT 'member', status TEXT NOT NULL DEFAULT 'pending', PRIMARY KEY(group_id,user_id));
CREATE TABLE posts (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), kind TEXT NOT NULL DEFAULT 'post', parent_id TEXT REFERENCES posts(id), group_id TEXT REFERENCES groups(id), category TEXT NOT NULL DEFAULT '', title TEXT NOT NULL DEFAULT '', content TEXT NOT NULL, media TEXT NOT NULL DEFAULT '', tournament_id TEXT, pinned INTEGER NOT NULL DEFAULT 0, locked INTEGER NOT NULL DEFAULT 0, removed INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE INDEX post_feed ON posts(kind,removed,created_at DESC);
CREATE INDEX post_parent ON posts(parent_id,created_at);
CREATE TABLE likes (user_id TEXT NOT NULL REFERENCES users(id), post_id TEXT NOT NULL REFERENCES posts(id), PRIMARY KEY(user_id,post_id));
CREATE TABLE messages (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), channel TEXT NOT NULL, recipient_id TEXT REFERENCES users(id), content TEXT NOT NULL, removed INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE INDEX message_channel ON messages(channel,created_at DESC);
CREATE TABLE blocks (user_id TEXT NOT NULL REFERENCES users(id), target_id TEXT NOT NULL REFERENCES users(id), PRIMARY KEY(user_id,target_id));
CREATE TABLE mutes (user_id TEXT NOT NULL REFERENCES users(id), target_id TEXT NOT NULL REFERENCES users(id), PRIMARY KEY(user_id,target_id));
CREATE TABLE notifications (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), text TEXT NOT NULL, link TEXT NOT NULL, is_read INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE INDEX notification_user ON notifications(user_id,created_at DESC);
CREATE TABLE reports (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), target_type TEXT NOT NULL, target_id TEXT NOT NULL, reason TEXT NOT NULL, detail TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open', created_at TEXT NOT NULL);
CREATE TABLE moderation_logs (id TEXT PRIMARY KEY, actor_id TEXT NOT NULL, action TEXT NOT NULL, target_id TEXT NOT NULL, detail TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE forum_categories (name TEXT PRIMARY KEY);
INSERT INTO forum_categories VALUES ('General'),('Call of Duty'),('FPS'),('Fighting Games'),('Racing'),('Sports Games'),('Tournaments'),('Looking for Players'),('Looking for Groups'),('Technical Help');
CREATE TABLE media (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), kind TEXT NOT NULL, mime TEXT NOT NULL, data BLOB NOT NULL, created_at TEXT NOT NULL);
